-- Fin-Comply Task Assessment seed: 37 rule/signal templates.
-- Inactive rows represent context-only signals and must not generate standalone tasks.
-- Run after db/create_task_templates.sql; safe to rerun.
BEGIN;
ON CONFLICT (rule_id, signal_id) DO UPDATE SET
    task_title = EXCLUDED.task_title,
    task_description = EXCLUDED.task_description,
    responsible_team = EXCLUDED.responsible_team,
    priority = EXCLUDED.priority,
    remediation_steps = EXCLUDED.remediation_steps,
    is_active = EXCLUDED.is_active,
    updated_at = NOW();
COMMIT;

-- Expected: 37 total, 31 active, 6 contextual/inactive.
SELECT COUNT(*) AS total_templates,
       COUNT(*) FILTER (WHERE is_active) AS active_templates,
       COUNT(*) FILTER (WHERE NOT is_active) AS contextual_templates
FROM task_templates;
